mapper.select:
SELECT 
  FROM fnd32_account
 WHERE fnd32_account_id = #{accountId}
   AND fnd32_company_id = #{companyId}

mapper.delete:
DELETE FROM fnd32_account
 WHERE fnd32_company_id = #{companyId}
   AND fnd32_account_id IN
#{accountId}

mapper.select:
SELECT sys15_corp_id
  FROM sys15_corp
 WHERE sys15_company_id = #{companyId}
   AND sys15_corp_nm    = #{corpName}
   AND COALESCE(sys15_use_yn,'false') = 'true'
 LIMIT 1
